def choose_move(observation):
    # Use defensive .get for environment_name
    env = observation.get("environment_name", "resource_collection")
    sx, sy = observation.get("self_position", (0,0))
    ox, oy = observation.get("opponent_position", (0,0))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            dx = 0
            dy = 0
            if ox > sx:
                dx = 1
            elif ox < sx:
                dx = -1
            if oy > sy:
                dy = 1
            elif oy < sy:
                dy = -1
            return [dx, dy]
        corners = [
            [0, 0],
            [0, observation.get("grid_height", 1) - 1],
            [observation.get("grid_width", 1) - 1, 0],
            [observation.get("grid_width", 1) - 1, observation.get("grid_height", 1) - 1],
        ]
        # Determine target corner furthest from opponent
        target = max(corners, key=lambda item: abs(item[0] - ox) + abs(item[1] - oy))
        dx = 0
        dy = 0
        if target[0] > sx:
            dx = 1
        elif target[0] < sx:
            dx = -1
        if target[1] > sy:
            dy = 1
        elif target[1] < sy:
            dy = -1
        return [dx, dy]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        dx = 0
        dy = 0
        if best[0] > sx:
            dx = 1
        elif best[0] < sx:
            dx = -1
        if best[1] > sy:
            dy = 1
        elif best[1] < sy:
            dy = -1
        return [dx, dy]

    resources = observation.get("resources") or []
    if not resources:
        dx = 0
        dy = 0
        if ox > sx:
            dx = 1
        elif ox < sx:
            dx = -1
        if oy > sy:
            dy = 1
        elif oy < sy:
            dy = -1
        return [dx, dy]
    best_resource = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
    dx = 0
    dy = 0
    if best_resource[0] > sx:
        dx = 1
    elif best_resource[0] < sx:
        dx = -1
    if best_resource[1] > sy:
        dy = 1
    elif best_resource[1] < sy:
        dy = -1
    return [dx, dy]
